def lower_bound(items, target):
    left = 0
    right = len(items)
    while left < right:
        mid = (left + right) // 2
        if items[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

print(lower_bound([1, 3, 3, 5, 8], 3))
print(lower_bound([1, 3, 3, 5, 8], 0))
print(lower_bound([1, 3, 3, 5, 8], 9))

